/**
 * Public MLB pitcher study references, retrieved from official MLB sources.
 * Generated public-only snapshot; see docs/PITCHER_STUDY_SOURCES.md for checks.
 * Pitch types stay exact. Generic Fastball / Breaking Ball, Two-Seam Fastball,
 * Other, and unsupported Statcast types have no inferred counterpart here.
 * Listed size is not body composition. Raw college and MLB velocity/spin are
 * not calibrated, and no mechanical similarity or future performance is implied.
 * No runtime request or private athlete data is used by this module.
 */
export type PitcherStudyPitchReference = Readonly<{
  pitchType: "Four-Seam Fastball" | "Sinker" | "Cutter" | "Slider" | "Sweeper" | "Curveball" | "Changeup" | "Splitter" | "Knuckleball";
  statcastCode: "FF" | "SI" | "FC" | "SL" | "ST" | "CU" | "CH" | "FS" | "KN";
  /** Classified pitch count; not a metric-valid spin/velocity reading count. */
  pitchCount: number;
  /** Source percentage of all season pitches, including types omitted here. */
  usagePercent: number;
  /** Source-published mean release velocity in mph, retained at source precision. */
  averageVelocity: number;
  /** Source-published mean total spin in RPM; not active spin or pitch movement. */
  averageSpin: number | null;
}>;

export type PitcherStudyReference = Readonly<{
  id: number;
  name: string;
  throws: "R" | "L" | null;
  heightInches: number;
  weightLb: number;
  /** Verified season count, including supported/unsupported and sparse types. */
  totalPitches: number;
  pitches: readonly PitcherStudyPitchReference[];
}>;

